// Owner bootstrap script (spec 2026-10-27 §0 step C4). Keys are generated by the script at test
// time into a temp dir; a stub `gh` captures what would be stored and lets us decrypt the result.
import { test } from "node:test";
import assert from "node:assert/strict";
import { execFileSync, spawnSync } from "node:child_process";
import {
  mkdtempSync,
  mkdirSync,
  writeFileSync,
  readFileSync,
  readdirSync,
  chmodSync,
  rmSync,
  statSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { fileURLToPath } from "node:url";

const SCRIPT = fileURLToPath(new URL("../scripts/owner/bootstrap-secrets.sh", import.meta.url));

function has(cmd, args, match) {
  const r = spawnSync(cmd, args, { encoding: "utf8" });
  return r.status === 0 && (!match || match.test(r.stdout + r.stderr));
}
const tools =
  has("sops", ["--version"], /^sops 3\.13\.3/m) &&
  has("age-keygen", ["--version"]) &&
  has("jq", ["--version"]);
const skip = tools ? false : "needs sops 3.13.3, age-keygen and jq on PATH";

test("bootstrap-secrets.sh parses", () => {
  execFileSync("bash", ["-n", SCRIPT]);
});

test("self-test round-trips", { skip }, () => {
  const out = execFileSync("bash", [SCRIPT, "--self-test"], { encoding: "utf8" });
  assert.match(out, /self-test ok/);
});

test("bootstrap writes encrypted bundles and stores keys only via stdin", { skip }, () => {
  const tmp = mkdtempSync(join(tmpdir(), "boot-"));
  try {
    const bin = join(tmp, "bin");
    const store = join(tmp, "store");
    mkdirSync(bin);
    mkdirSync(store);
    // stub gh: `secret set` saves stdin per env; records argv; api calls succeed with empty output
    writeFileSync(
      join(bin, "gh"),
      `#!/usr/bin/env bash\necho "$*" >> "${store}/argv"\nif [ "$1" = secret ]; then r="$7"; cat > "${store}/key-$(printf %s "$r" | tr / _)-$5"; fi\nexit 0\n`,
    );
    chmodSync(join(bin, "gh"), 0o755);
    const repo = join(tmp, "secrets");
    mkdirSync(repo);
    execFileSync("git", ["init", "-q", repo]);
    const owner = execFileSync("bash", ["-c", "age-keygen 2>/dev/null | age-keygen -y"], {
      encoding: "utf8",
    }).trim();
    const env = { ...process.env, PATH: `${bin}:${process.env.PATH}` };
    const out = execFileSync(
      "bash",
      [
        SCRIPT,
        "--secrets-dir",
        repo,
        "--owner-pub",
        owner,
        "--consumer",
        "acme/site:preview:github",
        "--consumer",
        "acme/site:prod:github",
        "--consumer",
        "acme/canary:prod:github",
        "--bundle",
        "prod/cloudflare=TOKEN,ACCOUNT@site-prod",
        "--bundle",
        "prod/canary=SMOKE@canary-prod",
      ],
      { env, input: "tok-value-1\nacct-value-2\nsmoke-value-3\n", encoding: "utf8" },
    );
    assert.match(out, /consumer prod site-prod age1/);
    assert.match(out, /no private key in the repo dir: ok/);
    const access = readFileSync(join(repo, "access.toml"), "utf8");
    assert.match(access, /name = "owner-1"\nkind = "human"/);
    assert.match(
      access,
      /path = "prod\/cloudflare\.sops\.yaml"\nrecipients = \["owner-1", "site-prod"\]/,
    );
    assert.match(
      access,
      /path = "prod\/canary\.sops\.yaml"\nrecipients = \["owner-1", "canary-prod"\]/,
    );
    assert.match(
      readFileSync(join(repo, ".sops.yaml"), "utf8"),
      /path_regex: \^prod\/cloudflare\\\.sops\\\.yaml\$/,
    );
    const enc = readFileSync(join(repo, "prod", "cloudflare.sops.yaml"), "utf8");
    assert.doesNotMatch(enc, /tok-value-1|acct-value-2/);
    assert.equal((enc.match(/recipient: age1/g) ?? []).length, 2); // owner + site-prod only
    const argv = readFileSync(join(store, "argv"), "utf8");
    assert.doesNotMatch(argv, /AGE-SECRET-KEY-/);
    const key = (repoName, envName) =>
      readFileSync(join(store, `key-acme_${repoName}-${envName}`), "utf8");
    const decrypt = (file, k) =>
      // Node's child stdin is a socket, which sops cannot open as /dev/stdin; decrypt the file.
      spawnSync("sops", ["decrypt", "--output-type", "json", join(repo, "prod", file)], {
        env: { ...process.env, SOPS_AGE_KEY: k },
        encoding: "utf8",
      });
    assert.match(key("site", "prod"), /^AGE-SECRET-KEY-1/);
    const ok = decrypt("cloudflare.sops.yaml", key("site", "prod"));
    assert.equal(ok.status, 0, ok.stderr);
    assert.deepEqual(JSON.parse(ok.stdout), { TOKEN: "tok-value-1", ACCOUNT: "acct-value-2" });
    assert.notEqual(decrypt("cloudflare.sops.yaml", key("canary", "prod")).status, 0); // other consumer
    assert.notEqual(decrypt("cloudflare.sops.yaml", key("site", "preview")).status, 0); // other env
    assert.deepEqual(JSON.parse(decrypt("canary.sops.yaml", key("canary", "prod")).stdout), {
      SMOKE: "smoke-value-3",
    });
    for (const f of readdirSync(repo, { recursive: true })) {
      if (String(f).startsWith(".git") || statSync(join(repo, String(f))).isDirectory()) continue;
      assert.doesNotMatch(readFileSync(join(repo, String(f))).toString(), /AGE-SECRET-KEY-/);
    }
  } finally {
    rmSync(tmp, { recursive: true, force: true });
  }
});
